    int tot_obs;
    array[dims(s)[1]] real ret;
    tot_obs = dims(s)[1];

    //apply logistic function to each observation
    for(obs in 1:tot_obs) {
      ret[obs] = a[obs]/(1 + exp(-b[obs]*s[obs]+c[obs])) + d[obs];
    }

    return ret;
